namespace ghidra.app.plugin.core.debug.gui.emulation;



using ghidra.program.model.address;
using ghidra.program.model.address;

public abstract class AddressInputVerifier : InputVerifier {
	private AddressFactory factory;

	public AddressInputVerifier(AddressFactory factory) {
		this.factory = factory;
	}

	/* @Override */
	public bool verify(JComponent input) {
		if (!(input is JTextField text)) {
			throw new IllegalArgumentException(
				"Only JTextField is supported. Got %s".formatted(input.GetType()));
		}
		string str = text.getText();
		try {
			Address address = factory.getAddress(str);
			if (address == null) {
				reject("Invalid address: %s".formatted(str));
				return false;
			}
			if (!verifyAddress(address)) {
				reject("Invalid address: %s".formatted(str));
				return false;
			}
			return true;
		}
		catch (Exception e) {
			reject("%s while parsing '%s'".formatted(e.getMessage(), str));
			return false;
		}
	}

	protected abstract bool verifyAddress(Address address);

	protected abstract void reject(string message);
}
